/* a piece's name or description to show (furn.h): decoded into buf where
 * the text is packed, else the string itself */
const char *doomo_furn_text(const char *p, char *buf, int cap)
{
#ifdef FURN_PACKED_TEXT
    const uint8_t *s = (const uint8_t *)p;
    uint32_t pos = 0;
    int n = 0;
    if (!p || !buf || cap <= 0) return "";
    if (s < furn_text || s >= furn_text + sizeof(furn_text)) return p;   /* not packed */
    for (;;) {
        unsigned code = 0, first = 0, index = 0, l, c = 0;
        for (l = 1; l <= 16; l++) {
            code |= (s[pos >> 3] >> (7 - (pos & 7))) & 1u;
            pos++;
            if (code - first < furn_huff_n[l]) { c = furn_huff_sym[index + code - first]; break; }
            index += furn_huff_n[l];
            first = (first + furn_huff_n[l]) << 1;
            code <<= 1;
        }
        if (!c || l > 16) break;
        if (n < cap - 1) buf[n++] = (char)c;
    }
    buf[n] = 0;
    return buf;
#else
    (void)buf; (void)cap;
    return p ? p : "";
#endif
}

